  'shader.kicker': { en: 'URP shader code uses HLSL and URP includes. A useful shader is more than its visible color: passes and tags tell URP when it participates in depth, lighting and shadows.', ru: 'Шейдер URP использует HLSL и include-файлы URP. Полезный шейдер — это не только видимый цвет: проходы и теги сообщают URP, когда он участвует в depth, освещении и тенях.' },
  'shader.labTag': { en: 'INTERACTIVE · SHADER ANATOMY', ru: 'ИНТЕРАКТИВ · АНАТОМИЯ ШЕЙДЕРА' },
