  'shader.lit': { en: '<b>Lit</b> uses physically based lighting and supports more material features. <b>Simple Lit</b> trades some fidelity for a cheaper shading model.', ru: '<b>Lit</b> использует физически корректное освещение и поддерживает больше свойств материала. <b>Simple Lit</b> меняет часть точности на более дешёвую модель света.' },
  'shader.graph': { en: '<b>Shader Graph</b> is the artist-facing authoring tool. Handwritten HLSL remains useful when you need exact control, reusable includes, or a custom Renderer Feature.', ru: '<b>Shader Graph</b> — инструмент для художников. Ручной HLSL полезен, когда нужен точный контроль, повторно используемые includes или пользовательский Renderer Feature.' },
  'shader.visible': { en: 'VISIBLE', ru: 'ВИДЕН' },
