  'graph.renderObjects': { en: 'A built-in Renderer Feature that filters objects by Layer Mask and can override material or render state at a chosen pipeline event.', ru: 'Встроенный Renderer Feature фильтрует объекты по Layer Mask и может заменить материал или render state в выбранной точке пайплайна.' },
