  'graph.phase.setup.copy': { en: '<b>Setup:</b> C# records every candidate pass and declares resource handles. No texture memory is allocated yet.', ru: '<b>Сборка:</b> C# записывает все возможные проходы и объявляет handles ресурсов. Память текстур пока не выделяется.' },
